function maxGamesWinner(n) {
    if (n === 2n) return 1n;
    let low = 1n, high = 1000000000n; // sufficient for n up to 1e18

    while (low <= high) {
        let mid = (low + high) >> 1n;
        // total players that can be eliminated by a winner with mid games:
        // sum_{i=0}^{mid-1} 2^i = 2^mid - 1
        let total = (1n << mid) - 1n;
        if (total <= n - 1n) {
            low = mid + 1n;
        } else {
            high = mid - 1n;
        }
    }
    return high;
}

